contract_clause(contrato_ocs_303_2016, clausula_primeira_objeto, 'CLÁUSULA PRIMEIRA – OBJETO \nO presente Contrato tem por objeto a prestação de serviços continuados, sem \ndedicação exclusiva de mão-de-obra, especializados em segurança cibernética \nprestado  por  Centro  de  Operações  de  Segurança  Cibernética  (Cyber  Security \nOperation  Center  –  CSOC)  para  o  Banco  Nacional  de  Desenvolvimento \nEconômico  e  Social  –  BNDES,  conforme  especificações  constantes  do  Termo \nde Referência (Anexo I do Edital do Pregão Eletrônico nº 07/2024 - BNDES) e \nda proposta apresentada pelo CONTRATADO, respectivamente, Anexos I e II \ndeste Contrato.', 'O presente Contrato tem por objeto a prestação de serviços continuados, sem \ndedicação exclusiva de mão-de-obra, especializados em segurança cibernética \nprestado  por  Centro  de  Operações  de  Segurança  Cibernética  (Cyber  Security \nOperation  Center  –  CSOC)  para  o  Banco  Nacional  de  Desenvolvimento \nEconômico  e  Social  –  BNDES,  conforme  especificações  constantes  do  Termo \nde Referência (Anexo I do Edital do Pregão Eletrônico nº 07/2024 - BNDES) e \nda proposta apresentada pelo CONTRATADO, respectivamente, Anexos I e II \ndeste Contrato.').
contract_clause_fact(contrato_ocs_303_2016, clausula_primeira_objeto, objeto, 'prestação de serviços continuados, sem \ndedicação exclusiva de mão-de-obra, especializados em segurança cibernética \nprestado  por  Centro  de  Operações  de  Segurança  Cibernética  (Cyber  Security \nOperation  Center  –  CSOC)  para  o  Banco  Nacional  de  Desenvolvimento \nEconômico  e  Social  –  BNDES', 'trecho_literal').

contract_clause(contrato_ocs_303_2016, clausula_segunda_vigencia, 'CLÁUSULA SEGUNDA – VIGÊNCIA \nO prazo de vigência do presente Contrato será de até 60 (sessenta) meses a \ncontar da data de sua assinatura, sendo de: \n\nI.    até  6  (seis)  meses,  contados  da  assinatura  do  contrato,  para  execução  da \nimplantação, incluindo todas as fases até a emissão do Termo de Recebimento \nDefinitivo; \nII.  até  60  (sessenta)  meses  a  contar  da  emissão  do  Termo  de  Recebimento \nDefinitivo, com opção de rescisão por parte do BNDES a partir do 30º (trigésimo) \nmês  de  vigência,  desde  que  comunicada  com  antecedência  de  180  (cento  e \n oitenta) dias.', 'O prazo de vigência do presente Contrato será de até 60 (sessenta) meses a \ncontar da data de sua assinatura, sendo de: \n\nI.    até  6  (seis)  meses,  contados  da  assinatura  do  contrato,  para  execução  da \nimplantação, incluindo todas as fases até a emissão do Termo de Recebimento \nDefinitivo; \nII.  até  60  (sessenta)  meses  a  contar  da  emissão  do  Termo  de  Recebimento \nDefinitivo, com opção de rescisão por parte do BNDES a partir do 30º (trigésimo) \nmês  de  vigência,  desde  que  comunicada  com  antecedência  de  180  (cento  e \n oitenta) dias.').
contract_clause_fact(contrato_ocs_303_2016, clausula_segunda_vigencia, prazo_vigencia, '60 meses', 'trecho_literal').
contract_clause_fact(contrato_ocs_303_2016, clausula_segunda_vigencia, prazo_vigencia, '6 meses', 'I').
contract_clause_fact(contrato_ocs_303_2016, clausula_segunda_vigencia, prazo_vigencia, '60 meses', 'II').
contract_clause_fact(contrato_ocs_303_2016, clausula_segunda_vigencia, prazo_suspensao, '180 dias', 'II').

contract_clause(contrato_ocs_303_2016, clausula_terceira_local_prazo_condicoes_execucao_objeto, 'CLÁUSULA  TERCEIRA  –  LOCAL,  PRAZO  E  CONDIÇÕES  DE  EXECUÇÃO \nDO OBJETO  \nA  execução  do  objeto  contratado  respeitará  as  especificações  constantes  do \nTermo  de  Referência  e  da  proposta  apresentada  pelo  CONTRATADO, \nrespectivamente, Anexos I e II deste Contrato.', 'A  execução  do  objeto  contratado  respeitará  as  especificações  constantes  do \nTermo  de  Referência  e  da  proposta  apresentada  pelo  CONTRATADO, \nrespectivamente, Anexos I e II deste Contrato.').
contract_clause_fact(contrato_ocs_303_2016, clausula_terceira_local_prazo_condicoes_execucao_objeto, referencia_execucao, ['Termo  de  Referência', 'proposta  apresentada  pelo  CONTRATADO, \nrespectivamente, Anexos I e II'], 'trecho_literal').

contract_clause(contrato_ocs_303_2016, clausula_quarta_niveis_servico, 'CLÁUSULA QUARTA – NÍVEIS DE SERVIÇO  \nOs serviços contratados deverão ser executados de acordo com os padrões de \nqualidade, disponibilidade e desempenho estipulados pelo BNDES, observados \nos níveis de serviço descritos no Anexo I (Termo de Referência) deste Contrato. \n\nParágrafo Único \nO descumprimento dos níveis de serviço acarretará a aplicação dos índices de \nredução do preço previstos no Anexo I (Termo de Referência) deste Contrato, \nsem  prejuízo  da  aplicação  das  penalidades  previstas  neste  Contrato,  quando \ncabíveis.', 'Os serviços contratados deverão ser executados de acordo com os padrões de \nqualidade, disponibilidade e desempenho estipulados pelo BNDES, observados \nos níveis de serviço descritos no Anexo I (Termo de Referência) deste Contrato. \n\nParágrafo Único \nO descumprimento dos níveis de serviço acarretará a aplicação dos índices de \nredução do preço previstos no Anexo I (Termo de Referência) deste Contrato, \nsem  prejuízo  da  aplicação  das  penalidades  previstas  neste  Contrato,  quando \ncabíveis.').
contract_clause_fact(contrato_ocs_303_2016, clausula_quarta_niveis_servico, padroes_servico, ['qualidade', 'disponibilidade', 'desempenho'], 'trecho_literal').
contract_clause_fact(contrato_ocs_303_2016, clausula_quarta_niveis_servico, consequencia_descumprimento_niveis, ['aplicação dos índices de \nredução do preço', 'aplicação  das  penalidades'], 'Parágrafo Único').

contract_clause(contrato_ocs_303_2016, clausula_quinta_recebimento_objeto, 'CLÁUSULA QUINTA – RECEBIMENTO DO OBJETO \nO  BNDES  efetuará  o  recebimento  do  objeto,  através  do  Gestor  do  Contrato, \nmencionados na Cláusula de Obrigações do BNDES deste Contrato, observado \no disposto no Anexo I (Termo de Referência) deste Contrato.', 'O  BNDES  efetuará  o  recebimento  do  objeto,  através  do  Gestor  do  Contrato, \nmencionados na Cláusula de Obrigações do BNDES deste Contrato, observado \no disposto no Anexo I (Termo de Referência) deste Contrato.').
contract_clause_fact(contrato_ocs_303_2016, clausula_quinta_recebimento_objeto, responsavel_recebimento, 'Gestor  do  Contrato', 'trecho_literal').
contract_clause_fact(contrato_ocs_303_2016, clausula_quinta_recebimento_objeto, referencia_recebimento, 'Anexo I (Termo de Referência)', 'trecho_literal').

contract_clause(contrato_ocs_303_2016, clausula_sexta_preco, 'CLÁUSULA SEXTA – PREÇO  \nO  BNDES  pagará  ao  CONTRATADO,  pela  execução  do  objeto  contratado,  o \nvalor  de  até  R$  6.989.822,00  (seis  milhões,  novecentos  e  oitenta  e  nove  mil, \noitocentos e vinte e dois reais), conforme proposta apresentada (Anexo II deste \nContrato), observado o disposto na Cláusula de Pagamento deste Instrumento. \n\nContrato OCS nº 295/2024 \nContratante: BNDES \nContratado: KRYPTUS SEGURANÇA DA INFORMAÇÃO S.A. \n\n2                                                                                                                             \n\n \n \n \n \n \n \n \n \n \n \n \nClassificação: Documento Ostensivo (Lei nº 13.303/2016) \nUnidade Gestora: AJI/JULIC/GLIC4 \n\nParágrafo Primeiro \nNo  valor  ajustado  no  caput  desta  Cláusula  estão  incluídos  todos  os  insumos, \nencargos trabalhistas e tributos, inclusive contribuições fiscais e parafiscais, bem \ncomo quaisquer outras despesas necessárias à execução deste Contrato. \n\nParágrafo Segundo \nNa  hipótese  de  o  objeto  ser,  a  critério  do  BNDES,  parcialmente  executado  e \nrecebido,  os  valores  previstos  nesta  Cláusula  serão  proporcionalmente \nreduzidos, sem prejuízo da aplicação das penalidades cabíveis. \n\nParágrafo Terceiro \nCaso o BNDES não demande o total do objeto previsto neste Contrato, não será \ndevida indenização ao CONTRATADO.  \n\nParágrafo Quarto \nO CONTRATADO deverá arcar com os ônus decorrentes de eventual equívoco \nno dimensionamento dos quantitativos de sua proposta, devendo complementá-\nlos,  caso  os  quantitativos  previstos  inicialmente  em  sua  proposta  não  sejam \nsatisfatórios para o atendimento ao objeto deste Contrato;  \n\nParágrafo Quinto \nO  BNDES  não  se  compromete  à  utilização  do  total  estimado  de  horas \nextraordinárias,  sendo  pagas  somente  as  que  efetivamente  forem  realizadas, \nque  serão  aferidas através  de  planilhas  a  serem apresentadas, mensalmente, \npelo CONTRATADO.', 'O  BNDES  pagará  ao  CONTRATADO,  pela  execução  do  objeto  contratado,  o \nvalor  de  até  R$  6.989.822,00  (seis  milhões,  novecentos  e  oitenta  e  nove  mil, \noitocentos e vinte e dois reais), conforme proposta apresentada (Anexo II deste \nContrato), observado o disposto na Cláusula de Pagamento deste Instrumento. \n\nContrato OCS nº 295/2024 \nContratante: BNDES \nContratado: KRYPTUS SEGURANÇA DA INFORMAÇÃO S.A. \n\n2                                                                                                                             \n\n \n \n \n \n \n \n \n \n \n \n \nClassificação: Documento Ostensivo (Lei nº 13.303/2016) \nUnidade Gestora: AJI/JULIC/GLIC4 \n\nParágrafo Primeiro \nNo  valor  ajustado  no  caput  desta  Cláusula  estão  incluídos  todos  os  insumos, \nencargos trabalhistas e tributos, inclusive contribuições fiscais e parafiscais, bem \ncomo quaisquer outras despesas necessárias à execução deste Contrato. \n\nParágrafo Segundo \nNa  hipótese  de  o  objeto  ser,  a  critério  do  BNDES,  parcialmente  executado  e \nrecebido,  os  valores  previstos  nesta  Cláusula  serão  proporcionalmente \nreduzidos, sem prejuízo da aplicação das penalidades cabíveis. \n\nParágrafo Terceiro \nCaso o BNDES não demande o total do objeto previsto neste Contrato, não será \ndevida indenização ao CONTRATADO.  \n\nParágrafo Quarto \nO CONTRATADO deverá arcar com os ônus decorrentes de eventual equívoco \nno dimensionamento dos quantitativos de sua proposta, devendo complementá-\nlos,  caso  os  quantitativos  previstos  inicialmente  em  sua  proposta  não  sejam \nsatisfatórios para o atendimento ao objeto deste Contrato;  \n\nParágrafo Quinto \nO  BNDES  não  se  compromete  à  utilização  do  total  estimado  de  horas \nextraordinárias,  sendo  pagas  somente  as  que  efetivamente  forem  realizadas, \nque  serão  aferidas através  de  planilhas  a  serem apresentadas, mensalmente, \npelo CONTRATADO.').
contract_clause_fact(contrato_ocs_303_2016, clausula_sexta_preco, valor_maximo, '6.989.822,00', 'trecho_literal').
contract_clause_fact(contrato_ocs_303_2016, clausula_sexta_preco, valor_incluso, ['insumos', 'encargos trabalhistas', 'tributos', 'contribuições fiscais e parafiscais', 'quaisquer outras despesas'], 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_303_2016, clausula_sexta_preco, consequencia_execucao_parcial, 'valores serão proporcionalmente \nreduzidos', 'Parágrafo Segundo').
contract_clause_fact(contrato_ocs_303_2016, clausula_sexta_preco, consequencia_nao_demanda_total, 'não será \ndevida indenização', 'Parágrafo Terceiro').
contract_clause_fact(contrato_ocs_303_2016, clausula_sexta_preco, responsabilidade_contratado, 'arcar com os ônus decorrentes de eventual equívoco \nno dimensionamento dos quantitativos de sua proposta', 'Parágrafo Quarto').

